Definition fpv_minmax (op : fminmaxop) (fmt : ffmt) (a b : Z) : Z * fflags :=
  fp_minmax (fp_format fmt) (match op with F_MIN => false | F_MAX => true end) a b.
Lemma fpv_step_fminmax : forall (fx : FPState) segs regs pc mem rom w op fmt rd rs1 rs2,
  fetch_word segs pc = Some w -> is_ecall w = false ->
  decode_any w = Some (Fminmax op fmt rd rs1 rs2, 4%Z) ->
  RiscvSemantics.step segs (@mkst fx regs pc mem rom) =
  MachineOk (@mkst (mkFP (bvmap_set rd (fpv_box fmt (fst (fpv_minmax op fmt (fpv_read (@fp_regs fx) fmt rs1) (fpv_read (@fp_regs fx) fmt rs2)))) (@fp_regs fx))
                         (fpv_acc (@fp_csr fx) (snd (fpv_minmax op fmt (fpv_read (@fp_regs fx) fmt rs1) (fpv_read (@fp_regs fx) fmt rs2)))))
                   regs (v_addi pc 4) mem rom).
